// Improvements: security headers, rate limiting, input validation,
// error handling, 404 handling, and environment-based config.

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Security Headers (helmet sets X-Frame-Options, Content-Security-Policy,
//    X-Content-Type-Options, Strict-Transport-Security, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body Parsing — limit payload size to prevent large-body DoS attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Global Rate Limiting — throttles repeated requests from the same IP
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,     // return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — no sensitive data, no validation needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — validate & sanitize any query parameters before use
app.get('/users', (req, res, next) => {
  try {
    // Example: accept an optional numeric `id` query param
    const { id } = req.query;

    // Input validation: if provided, `id` must be a positive integer
    if (id !== undefined) {
      const parsedId = parseInt(id, 10);
      if (!Number.isInteger(parsedId) || parsedId <= 0 || String(parsedId) !== id.trim()) {
        return res.status(400).json({ error: 'Invalid id. Must be a positive integer.' });
      }

      // In a real app, use a parameterised query here — never interpolate directly
      const users = getAllUsers();
      const user = users.find((u) => u.id === parsedId);
      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }
      return res.json(user);
    }

    return res.json(getAllUsers());
  } catch (err) {
    next(err); // forward unexpected errors to the central error handler
  }
});

// ---------------------------------------------------------------------------
// 4. 404 Handler — catches requests to undefined routes
//    (must be defined after all valid routes)
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 5. Centralised Error Handler — catches errors forwarded via next(err)
//    Never expose stack traces or internal details to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error internally (replace with a proper logger in production)
  console.error('[Error]', err);

  // Return a generic message to the client
  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode === 500 ? 'An internal server error occurred.' : err.message,
  });
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Returns the user list. Replace with a real DB call in production. */
function getAllUsers() {
  return [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
}

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

