// Simple application — hardened for security best practices

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// -------------------------------------------------------------------
// 1. SECURITY HEADERS
//    helmet sets a suite of protective HTTP headers automatically,
//    including X-Content-Type-Options, X-Frame-Options, and CSP.
// -------------------------------------------------------------------
app.use(helmet());

// -------------------------------------------------------------------
// 2. REQUEST BODY PARSING WITH SIZE LIMIT
//    Prevents payload-based DoS by capping the accepted body size.
// -------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));

// -------------------------------------------------------------------
// 3. RATE LIMITING
//    Limits each IP to 100 requests per 15-minute window.
//    Adjust `max` and `windowMs` to match your production traffic.
// -------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// -------------------------------------------------------------------
// ROUTES
// -------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation example: optional `limit` query param
    const limit = req.query.limit !== undefined
      ? parseInt(req.query.limit, 10)
      : null;

    if (limit !== null && (isNaN(limit) || limit < 1 || limit > 100)) {
      // 400 Bad Request — never trust client-supplied values
      return res.status(400).json({
        error: 'Invalid limit. Must be an integer between 1 and 100.',
      });
    }

    // In a real app this data comes from a DB; kept static here for clarity
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    if (limit !== null) {
      users = users.slice(0, limit);
    }

    res.json(users);
  } catch (err) {
    // Forward unexpected errors to the global error handler below
    next(err);
  }
});

// -------------------------------------------------------------------
// 4. 404 HANDLER
//    Catches all unmatched routes and returns a clean JSON response
//    instead of leaking Express internals via the default HTML page.
// -------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// -------------------------------------------------------------------
// 5. GLOBAL ERROR HANDLER
//    Must have exactly four parameters for Express to recognise it.
//    Logs the full error server-side; only sends a generic message to
//    the client to avoid leaking stack traces or implementation details.
// -------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'An unexpected error occurred.' });
});

// -------------------------------------------------------------------
// 6. PORT FROM ENVIRONMENT
//    Never hardcode ports. Fall back to 3000 only in local dev.
// -------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = { app, server };

