/**
 * app.js — Express application with security best practices applied.
 *
 * Improvements over original:
 *  - Helmet for secure HTTP headers
 *  - express-rate-limit to prevent abuse
 *  - Body parser with size limit
 *  - Input validation via express-validator
 *  - Centralized error handler (no stack traces leaked to clients)
 *  - Catch-all 404 handler
 *  - Port read from environment variable
 *  - Structured logging (replacing raw console.log)
 */

'use strict';

const express = require('express');
const helmet = require('helmet');                          // Secure HTTP headers
const rateLimit = require('express-rate-limit');          // Rate limiting
const { query, validationResult } = require('express-validator'); // Input validation

const app = express();

// ---------------------------------------------------------------------------
// 1. Security Headers (helmet sets X-Content-Type-Options, X-Frame-Options,
//    Strict-Transport-Security, Content-Security-Policy, and more)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing — enforce a payload size limit to prevent memory exhaustion
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate limiting — cap requests per IP to reduce brute-force / DoS risk
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // Max 100 requests per window per IP
  standardHeaders: true,     // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // Disable X-RateLimit-* legacy headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Structured logger helper — never exposes internals in production
// ---------------------------------------------------------------------------
const logger = {
  info:  (...args) => console.log('[INFO] ', new Date().toISOString(), ...args),
  warn:  (...args) => console.warn('[WARN] ', new Date().toISOString(), ...args),
  error: (...args) => console.error('[ERROR]', new Date().toISOString(), ...args),
};

// ---------------------------------------------------------------------------
// 5. Routes
// ---------------------------------------------------------------------------

// --- GET /health ---
// No user input; safe as-is.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// --- GET /users ---
// Accepts an optional `?id=` query parameter with strict validation.
//
// Validation rules:
//   - `id` must be an integer if provided
//   - `id` must be positive (>= 1)
//   - Any unknown query params are ignored (not reflected back)
app.get(
  '/users',
  [
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('id must be a positive integer')
      .toInt(), // Sanitise: cast to Number so it is never used as a raw string
  ],
  (req, res, next) => {
    // Reject the request immediately if validation failed
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Static dataset — replace with a real DB query in production
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    const { id } = req.query;
    if (id !== undefined) {
      const user = users.find((u) => u.id === id);
      if (!user) {
        // 404 for missing resource, not a server error
        return res.status(404).json({ error: 'User not found.' });
      }
      return res.json(user);
    }

    res.json(users);
  }
);

// ---------------------------------------------------------------------------
// 6. Catch-all 404 handler — must come AFTER all valid routes
//    Avoids leaking framework info via Express's default HTML error page
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 7. Centralised error handler — Express calls this when next(err) is used
//    Signature MUST have 4 arguments for Express to recognise it as an
//    error handler.
//    NEVER send stack traces or internal details to the client in production.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  logger.error(err.stack || err.message);

  const statusCode = err.status || err.statusCode || 500;

  res.status(statusCode).json({
    error:
      process.env.NODE_ENV === 'production'
        ? 'An unexpected error occurred.'  // Hide details in production
        : err.message,                     // Show details in development
  });
});

// ---------------------------------------------------------------------------
// 8. Start server — port from environment variable with safe fallback
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);

// Only start listening when this file is run directly (not when imported by
// test suites — prevents port conflicts during testing)
if (require.main === module) {
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`);
  });
}

module.exports = app;

