'use strict';

// ── Dependencies ──────────────────────────────────────────────────────────────
// Run: npm install express helmet express-rate-limit morgan
const express = require('express');
const helmet  = require('helmet');          // Secure HTTP headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const morgan  = require('morgan');          // Request logging

const app = express();

// ── Security: Hide framework fingerprint & set secure headers ─────────────────
// helmet() sets: Content-Security-Policy, X-Frame-Options, X-Content-Type-Options,
// Strict-Transport-Security, and more. Removes X-Powered-By automatically.
app.use(helmet());

// ── Request logging ───────────────────────────────────────────────────────────
// 'combined' format logs IP, method, path, status, and user-agent — useful for
// auditing. Use a log-rotation library (e.g. rotating-file-stream) in production.
app.use(morgan('combined'));

// ── Body parsing with size limits ─────────────────────────────────────────────
// Prevents large-payload (DoS) attacks by capping request body size at 10 kb.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ── Global rate limiter ───────────────────────────────────────────────────────
// Applies to all routes. Limits each IP to 100 requests per 15-minute window.
// Adjust windowMs / max per your expected traffic profile.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable the deprecated X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ── Input validation helper ───────────────────────────────────────────────────
// Centralise validation logic so it can be reused and unit-tested independently.
// For larger projects, replace with a dedicated library such as zod or joi.
const validate = {
  /**
   * Returns true only for safe, positive integers (no floats, no negatives,
   * no coerced strings like "1 OR 1=1").
   */
  isPositiveInt(value) {
    const n = Number(value);
    return Number.isInteger(n) && n > 0;
  },

  /**
   * Strips characters that have no place in a plain name/email field.
   * Returns null when the value is absent or exceeds the length cap.
   */
  sanitizeString(value, { maxLength = 100 } = {}) {
    if (typeof value !== 'string') return null;
    const trimmed = value.trim();
    if (trimmed.length === 0 || trimmed.length > maxLength) return null;
    // Remove HTML/script-injection characters
    return trimmed.replace(/[<>"'`;]/g, '');
  },
};

// ── Routes ────────────────────────────────────────────────────────────────────

// Health check — intentionally minimal; never expose internal system details here.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — demonstrates query-param validation and sanitization.
app.get('/users', (req, res, next) => {
  try {
    // --- Validate optional ?page and ?limit query params ---
    const rawPage  = req.query.page  ?? '1';
    const rawLimit = req.query.limit ?? '20';

    if (!validate.isPositiveInt(rawPage)) {
      return res.status(400).json({ error: 'Invalid "page" parameter. Must be a positive integer.' });
    }
    if (!validate.isPositiveInt(rawLimit)) {
      return res.status(400).json({ error: 'Invalid "limit" parameter. Must be a positive integer.' });
    }

    const page  = parseInt(rawPage,  10);
    const limit = Math.min(parseInt(rawLimit, 10), 100); // Cap page size at 100

    // --- Validate optional ?search query param ---
    let search = null;
    if (req.query.search !== undefined) {
      search = validate.sanitizeString(req.query.search, { maxLength: 50 });
      if (search === null) {
        return res.status(400).json({ error: 'Invalid "search" parameter.' });
      }
    }

    // In a real application, `page`, `limit`, and `search` would be passed to
    // a data layer using parameterised queries — never interpolated into SQL.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    res.json({ data: users, page, limit });
  } catch (err) {
    // Forward unexpected errors to the global error handler below.
    next(err);
  }
});

// ── 404 handler ───────────────────────────────────────────────────────────────
// Must be placed after all valid routes. Returns JSON (not Express's HTML page),
// so no framework information is leaked.
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ── Global error handler ──────────────────────────────────────────────────────
// Express identifies this as an error handler via the four-argument signature.
// - Logs the full error server-side for debugging.
// - Returns only a generic message to the client to avoid leaking internals.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${req.method} ${req.path}:`, err);

  const statusCode = Number.isInteger(err.status) ? err.status : 500;

  // Never expose stack traces or internal messages to clients in production.
  const message = process.env.NODE_ENV === 'production'
    ? 'An unexpected error occurred.'
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ── Server startup ────────────────────────────────────────────────────────────
// Read port from the environment so the same artifact runs in every environment
// without code changes (12-factor app principle).
const PORT = parseInt(process.env.PORT ?? '3000', 10);

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${process.env.NODE_ENV ?? 'development'}]`);
});

module.exports = app;

