'use strict';

// ------------------------------------------------------------
// Dependencies
// Run: npm install express helmet express-rate-limit morgan
// ------------------------------------------------------------
const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan  = require('morgan');

const app  = express();
const PORT = process.env.PORT || 3000;

// ------------------------------------------------------------
// 1. Security Headers (helmet sets X-Frame-Options,
//    X-Content-Type-Options, HSTS, CSP, and more)
// ------------------------------------------------------------
app.use(helmet());

// ------------------------------------------------------------
// 2. Request Logging (use 'combined' in production for
//    full Apache-style logs; 'dev' for local development)
// ------------------------------------------------------------
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ------------------------------------------------------------
// 3. Body Parsing with size limit (prevents large-payload DoS)
// ------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

