/**
 * app.js — Express application with security best practices applied.
 *
 * Improvements made:
 *  - Added helmet for secure HTTP headers
 *  - Added express-rate-limit to prevent abuse
 *  - Added express.json() with a body size limit
 *  - Added input validation for query parameters
 *  - Added a 404 handler for unknown routes
 *  - Added a global error handler to avoid leaking stack traces
 *  - Moved port config to an environment variable with a safe fallback
 */

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// Security Middleware
// ---------------------------------------------------------------------------

// Set secure HTTP response headers (X-Frame-Options, CSP, HSTS, etc.)
app.use(helmet());

// Parse JSON request bodies, capped at 10kb to prevent payload attacks
app.use(express.json({ limit: '10kb' }));

// Apply rate limiting to all requests: max 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  // Input validation: reject unexpected query parameters
  const allowedParams = new Set(['page', 'limit']);
  const receivedParams = Object.keys(req.query);
  const unexpectedParams = receivedParams.filter((p) => !allowedParams.has(p));

  if (unexpectedParams.length > 0) {
    return res.status(400).json({
      error: `Unexpected query parameter(s): ${unexpectedParams.join(', ')}`,
    });
  }

  // Validate and sanitize pagination parameters
  const page = parseInt(req.query.page, 10);
  const limit = parseInt(req.query.limit, 10);

  if (req.query.page !== undefined && (isNaN(page) || page < 1)) {
    return res.status(400).json({ error: "'page' must be a positive integer." });
  }

  if (req.query.limit !== undefined && (isNaN(limit) || limit < 1 || limit > 100)) {
    return res.status(400).json({ error: "'limit' must be an integer between 1 and 100." });
  }

  try {
    // NOTE: In production, replace this with a parameterised database query.
    // Never interpolate user input directly into query strings.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 404 Handler — must be placed after all valid routes
// ---------------------------------------------------------------------------

app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// Global Error Handler — must have exactly 4 arguments for Express to
// recognise it as an error-handling middleware
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  // Never expose stack traces or internal error details to clients
  res.status(500).json({ error: 'An internal server error occurred.' });
});

// ---------------------------------------------------------------------------
// Server Startup
// ---------------------------------------------------------------------------

// Read port from environment so the value is never hardcoded for deployment
const PORT = parseInt(process.env.PORT, 10) || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

