'use strict';

// ------------------------------------------------------------
// Dependencies
// npm install express helmet express-rate-limit
// ------------------------------------------------------------
const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ------------------------------------------------------------
// 1. SECURITY HEADERS
// helmet sets a suite of security-relevant HTTP headers and
// removes the "X-Powered-By: Express" fingerprint header.
// ------------------------------------------------------------
app.use(helmet());

// ------------------------------------------------------------
// 2. BODY PARSING WITH SIZE LIMIT
// Limits JSON payloads to 10kb to prevent large-payload DoS.
// ------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));

// ------------------------------------------------------------
// 3. RATE LIMITING
// Restricts each IP to 100 requests per 15-minute window.
// Adjust windowMs / max to match your traffic expectations.
// ------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ------------------------------------------------------------
// 4. SIMPLE REQUEST LOGGER
// Replace with a structured logger (e.g. winston/pino) in
// production. Never log sensitive fields like passwords.
// ------------------------------------------------------------
app.use((req, _res, next) => {
  const { method, path, ip } = req;
  console.log(`[${new Date().toISOString()}] ${method} ${path} - ${ip}`);
  next();
});

// ------------------------------------------------------------
// ROUTES
// ------------------------------------------------------------

// GET /health — no sensitive data, safe to be public
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — example of query param validation
// In a real app, protect this with authentication middleware.
app.get('/users', (req, res, next) => {
  try {
    // Validate & sanitize the optional ?id= query parameter.
    const { id } = req.query;

    if (id !== undefined) {
      const parsed = parseInt(id, 10);

      // Reject non-integer or non-positive values immediately.
      if (!Number.isInteger(parsed) || parsed <= 0) {
        return res.status(400).json({
          error: 'Invalid query parameter: "id" must be a positive integer.',
        });
      }

      // NOTE: In production, fetch from a database using a
      // parameterised query — never interpolate user input into SQL.
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob',   email: 'bob@example.com'   },
      ];

      const user = users.find((u) => u.id === parsed);

      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }

      return res.json(user);
    }

    // Return all users when no filter is supplied.
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ]);
  } catch (err) {
    // Forward unexpected errors to the global error handler below.
    next(err);
  }
});

// ------------------------------------------------------------
// 5. 404 HANDLER — catches requests to any undefined route
// Returns JSON (not HTML) to stay consistent with the API.
// ------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ------------------------------------------------------------
// 6. GLOBAL ERROR HANDLER
// Must have exactly four parameters so Express recognises it
// as an error-handling middleware.
// Hides internal details from the client in production to
// avoid leaking stack traces or implementation details.
// ------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Always log the full error internally for debugging.
  console.error(`[ERROR] ${err.stack || err.message}`);

  const isProd = process.env.NODE_ENV === 'production';
  res.status(err.status || 500).json({
    error: isProd ? 'An internal server error occurred.' : err.message,
  });
});

// ------------------------------------------------------------
// 7. SERVER STARTUP
// Reads port from the environment; falls back to 3000 locally.
// ------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

// Only start listening when this file is run directly, not when
// it is imported by tests (which call app directly).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

