/**
 * app.js — Express application with security-hardened error handling
 * and input validation best practices applied.
 */

'use strict';

const express = require('express');
const helmet = require('helmet');         // Secure HTTP headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Security Headers (helmet sets X-Content-Type-Options, X-Frame-Options,
//    Content-Security-Policy, and more in one call)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing with a strict size limit to prevent payload-based DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Global rate limiter — max 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Input validation helper
//    Centralising validation keeps route handlers clean and ensures
//    consistent sanitisation across the application.
// ---------------------------------------------------------------------------

/**
 * Validates that a value is a positive integer (e.g. a safe database ID).
 * @param {unknown} value
 * @returns {number|null} Parsed integer, or null if invalid.
 */
function parsePositiveInt(value) {
  if (value === undefined || value === null) return null;
  const num = Number(value);
  if (!Number.isInteger(num) || num <= 0 || num > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  return num;
}

/**
 * Validates a string is non-empty and within an allowed length.
 * @param {unknown} value
 * @param {number} maxLength
 * @returns {string|null} Trimmed string, or null if invalid.
 */
function parseString(value, maxLength = 100) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (trimmed.length === 0 || trimmed.length > maxLength) return null;
  return trimmed;
}

// ---------------------------------------------------------------------------
// 5. Routes
// ---------------------------------------------------------------------------

// Static data — in a real app this would come from a validated data layer
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

/**
 * GET /health
 * Simple liveness check. Returns no sensitive runtime information.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full user list.
 *
 * Optional query parameter:
 *   ?id=<positive integer>  — filter to a single user by ID
 */
app.get('/users', (req, res) => {
  // If an 'id' query param is present, validate and filter
  if (req.query.id !== undefined) {
    const id = parsePositiveInt(req.query.id);

    if (id === null) {
      // 400 Bad Request — invalid input, no stack trace exposed
      return res.status(400).json({
        error: 'Invalid query parameter: "id" must be a positive integer.',
      });
    }

    const user = USERS.find((u) => u.id === id);
    if (!user) {
      return res.status(404).json({ error: 'User not found.' });
    }

    return res.json(user);
  }

  res.json(USERS);
});

// ---------------------------------------------------------------------------
// 6. 404 handler — catches all unmatched routes before the error handler
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 7. Global error handler
//    Must be defined with exactly four parameters so Express treats it as
//    an error-handling middleware.
//    IMPORTANT: never expose err.stack or internal details to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
