// Simple application — improved for error handling and input validation
'use strict';

const express = require('express');
const helmet  = require('helmet');        // Adds secure HTTP headers
const rateLimit = require('express-rate-limit'); // Basic DoS protection

const app  = express();
const PORT = parseInt(process.env.PORT, 10) || 3000;
const IS_PRODUCTION = process.env.NODE_ENV === 'production';

// ─── Security Middleware ──────────────────────────────────────────────────────

// Sets X-Content-Type-Options, X-Frame-Options, HSTS, etc.
app.use(helmet());

// Parse JSON bodies with a strict size cap to prevent payload-based DoS.
app.use(express.json({ limit: '10kb' }));

// Global rate limiter: max 100 requests per 15-minute window per IP.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,   // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,     // Disable X-RateLimit-* legacy headers
  message: { error: 'Too many requests — please try again later.' },
});
app.use(limiter);

// ─── Input Validation Helper ──────────────────────────────────────────────────

/**
 * Validates that a value is a safe positive integer (e.g. for ID params).
 * Returns the parsed integer, or null if invalid.
 *
 * @param {*} value
 * @returns {number|null}
 */
function parsePositiveInt(value) {
  const n = parseInt(value, 10);
  return Number.isInteger(n) && n > 0 ? n : null;
}

// ─── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Example: validate an optional ?limit= query param before using it.
    const rawLimit = req.query.limit;
    let limit = 50; // safe default

    if (rawLimit !== undefined) {
      const parsed = parsePositiveInt(rawLimit);
      if (parsed === null || parsed > 100) {
        return res.status(400).json({
          error: 'Invalid "limit" parameter — must be a positive integer no greater than 100.',
        });
      }
      limit = parsed;
    }

    // Static data for now; in a real app this would come from a DB.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    res.json(users.slice(0, limit));
  } catch (err) {
    next(err); // Forward unexpected errors to the centralized error handler
  }
});

// ─── 404 Handler ─────────────────────────────────────────────────────────────

app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ─── Centralized Error Handler ────────────────────────────────────────────────
// Must have exactly four parameters so Express recognises it as an error handler.

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Always log the full error server-side for observability.
  console.error('[ERROR]', err);

  // Never leak stack traces or internal messages to clients in production.
  const message = IS_PRODUCTION
    ? 'An unexpected error occurred.'
    : err.message;

  res.status(err.status || 500).json({ error: message });
});

// ─── Start Server ─────────────────────────────────────────────────────────────

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
  });
}

module.exports = app;

